         assert!(scrubbed.contains("[PATH]"));
         assert!(!scrubbed.contains("/home/user"));
     }
+
+    // --- TelemetryConsent Display ---
+
+    #[test]
+    fn consent_display_send() {
+        assert_eq!(TelemetryConsent::Send.to_string(), "send");
+    }
+
+    #[test]
+    fn consent_display_no_thanks() {
+        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
+    }
+
+    #[test]
+    fn consent_display_always() {
+        assert_eq!(TelemetryConsent::Always.to_string(), "always");
+    }
+
+    #[test]
+    fn consent_display_never() {
+        assert_eq!(TelemetryConsent::Never.to_string(), "never");
+    }
+
+    // --- Scrubbing edge cases ---
+
+    #[test]
+    fn scrub_empty_input() {
+        let scrubbed = scrub_for_telemetry("", &HashMap::new());
+        assert_eq!(scrubbed, "");
+    }
+
+    #[test]
+    fn scrub_removes_tmp_paths() {
+        let input = "wrote to /tmp/build-cache/output.o";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(!scrubbed.contains("/tmp/build-cache"));
+    }
+
+    #[test]
+    fn scrub_removes_windows_paths() {
+        let input = r"Error at C:\Users\brenna\project\main.rs";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(!scrubbed.contains(r"C:\Users\brenna"));
+    }
+
+    #[test]
+    fn scrub_removes_slack_xoxb_tokens() {
+        let input = "token: xoxb-123456789012-abcdefghijABCDEFGHIJ";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("xoxb-"));
+    }
+
+    #[test]
+    fn scrub_removes_slack_xoxp_tokens() {
+        let input = "token: xoxp-987654321098-zyxwvutsrqponmlkjihg";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("xoxp-"));
+    }
+
+    #[test]
+    fn scrub_removes_github_oauth_tokens() {
+        let input = "auth: gho_abcdefghijklmnopqrstuvwxyz1234567890";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("gho_"));
+    }
+
+    #[test]
+    fn scrub_handles_combined_sensitive_data() {
+        let mut env = HashMap::new();
+        env.insert("DB_PASSWORD".to_string(), "hunter2".to_string());
+        let input =
+            "Error at /home/dev/app: auth ghp_aaaaaaaaaaaabbbbbbbbbbbbccccccccccdddddd with hunter2";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert!(!scrubbed.contains("/home/dev"));
+        assert!(!scrubbed.contains("ghp_"));
+        assert!(!scrubbed.contains("hunter2"));
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(scrubbed.contains("[REDACTED]"));
+    }
+
+    #[test]
+    fn scrub_ignores_empty_env_values() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "".to_string());
+        let input = "safe text here";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert_eq!(scrubbed, "safe text here");
+    }
+
+    #[test]
+    fn scrub_does_not_truncate_at_exactly_max_length() {
+        // Build a string of exactly MAX_ERROR_LENGTH chars using safe characters
+        let mut input = "ok ".repeat(MAX_ERROR_LENGTH / 3);
+        while input.len() < MAX_ERROR_LENGTH {
+            input.push('!');
+        }
+        assert_eq!(input.len(), MAX_ERROR_LENGTH);
+        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
+        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
+        assert!(!scrubbed.contains("...[truncated]"));
+    }
+
+    #[test]
+    fn scrub_truncates_at_max_length_plus_one() {
+        let mut input = "ok ".repeat(MAX_ERROR_LENGTH / 3);
+        while input.len() <= MAX_ERROR_LENGTH {
+            input.push('!');
+        }
+        assert!(input.len() > MAX_ERROR_LENGTH);
+        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
+        assert!(scrubbed.ends_with("...[truncated]"));
+    }
+
+    #[test]
+    fn scrub_handles_multiple_secrets_in_env() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "secret-aaa".to_string());
+        env.insert("SECRET_TOKEN".to_string(), "secret-bbb".to_string());
+        let input = "failed with secret-aaa and secret-bbb";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert!(!scrubbed.contains("secret-aaa"));
+        assert!(!scrubbed.contains("secret-bbb"));
+    }
+
+    #[test]
+    fn scrub_non_secret_env_values_preserved() {
+        let mut env = HashMap::new();
+        env.insert("PATH".to_string(), "/usr/bin".to_string());
+        env.insert("LANG".to_string(), "en_US".to_string());
+        let input = "using en_US locale";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert!(scrubbed.contains("en_US"));
+    }
+
+    // --- build_report ---
+
+    #[test]
+    fn build_report_with_none_exit_code() {
+        let report = build_report("test", "cmd", None, "err", "retry", &HashMap::new());
+        assert_eq!(report.exit_code, None);
+    }
+
+    #[test]
+    fn build_report_scrubs_command() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "my-secret".to_string());
+        let report = build_report(
+            "deploy",
+            "curl -H my-secret https://api.example.com",
+            Some(1),
+            "",
+            "retry",
+            &env,
+        );
+        assert!(!report.command_scrubbed.contains("my-secret"));
+    }
+
+    #[test]
+    fn build_report_platform_format() {
+        let report = build_report("test", "cmd", Some(0), "", "retry", &HashMap::new());
+        assert!(
+            report.platform.contains('-'),
+            "Platform should be OS-ARCH format: {}",
+            report.platform
+        );
+    }
+
+    // --- prompt_telemetry ---
+
+    #[test]
+    fn telemetry_prompt_returns_always() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "always");
+
+        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
+        assert_eq!(result, TelemetryConsent::Always);
+    }
+
+    #[test]
+    fn telemetry_prompt_returns_never() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "never");
+
+        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
+        assert_eq!(result, TelemetryConsent::Never);
+    }
+
+    #[test]
+    fn telemetry_prompt_unknown_saved_preference_shows_prompt() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "send");
+
+        let result = prompt_telemetry(&mut ui, &report, Some("garbage")).unwrap();
+        assert_eq!(result, TelemetryConsent::Send);
+        assert!(
+            !ui.prompts_shown().is_empty(),
+            "Should show prompt for unknown preference"
+        );
+    }
+
+    #[test]
+    fn telemetry_prompt_displays_step_and_command() {
+        let report = build_report(
+            "bundler",
+            "bundle install",
+            Some(1),
+            "gem error",
+            "retry",
+            &HashMap::new(),
+        );
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+        let messages = ui.messages();
+        let all_text = messages.join("\n");
+        assert!(all_text.contains("bundler"), "Should display step name");
+        assert!(
+            all_text.contains("bundle install"),
+            "Should display command"
+        );
+        assert!(all_text.contains("gem error"), "Should display error");
+        assert!(all_text.contains("retry"), "Should display recovery action");
+    }
+
+    #[test]
+    fn telemetry_prompt_displays_exit_code() {
+        let report = build_report("test", "cmd", Some(42), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+        let all_text = ui.messages().join("\n");
+        assert!(all_text.contains("42"), "Should display exit code");
+    }
+
+    #[test]
+    fn telemetry_prompt_hides_empty_error() {
+        let report = build_report("test", "cmd", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+        let all_text = ui.messages().join("\n");
+        assert!(
+            !all_text.contains("Error:"),
+            "Should not display error line when empty"
+        );
+    }
+
+    #[test]
+    fn telemetry_prompt_defaults_to_no_thanks_for_unknown_answer() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "unexpected_value");
+
+        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
+        assert_eq!(result, TelemetryConsent::NoThanks);
+    }
+
+    // --- save_report_to ---
+
+    #[test]
+    fn save_report_produces_valid_yaml_roundtrip() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let report = build_report(
+            "bundler",
+            "bundle install",
+            Some(1),
+            "build error",
+            "shell → retry",
+            &HashMap::new(),
+        );
+
+        let path = save_report_to(&report, temp.path()).unwrap();
+        let content = std::fs::read_to_string(&path).unwrap();
+        let deserialized: FailureReport = serde_yaml::from_str(&content).unwrap();
+
+        assert_eq!(deserialized.step_name, report.step_name);
+        assert_eq!(deserialized.command_scrubbed, report.command_scrubbed);
+        assert_eq!(deserialized.exit_code, report.exit_code);
+        assert_eq!(deserialized.error_scrubbed, report.error_scrubbed);
+        assert_eq!(deserialized.recovery_action, report.recovery_action);
+        assert_eq!(deserialized.bivvy_version, report.bivvy_version);
+        assert_eq!(deserialized.platform, report.platform);
+    }
+
+    #[test]
+    fn save_report_filename_contains_step_name() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let report = build_report("bundler", "cmd", Some(0), "", "retry", &HashMap::new());
+
+        let path = save_report_to(&report, temp.path()).unwrap();
+        let filename = path.file_name().unwrap().to_str().unwrap();
+        assert!(
+            filename.contains("bundler"),
+            "Filename should contain step name: {}",
+            filename
+        );
+        assert!(
+            filename.ends_with(".yml"),
+            "Filename should end with .yml: {}",
+            filename
+        );
+    }
+
+    #[test]
+    fn save_report_creates_nested_directory() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let nested = temp.path().join("a").join("b").join("c");
+        let report = build_report("test", "cmd", Some(0), "", "retry", &HashMap::new());
+
+        let path = save_report_to(&report, &nested).unwrap();
+        assert!(path.exists());
+        assert!(nested.is_dir());
+    }
+
+    #[test]
+    fn save_multiple_reports_no_clobber() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let report_a = build_report(
+            "step-a",
+            "cmd a",
+            Some(1),
+            "err a",
+            "retry",
+            &HashMap::new(),
+        );
+        let report_b = build_report("step-b", "cmd b", Some(2), "err b", "fix", &HashMap::new());
+
+        let path_a = save_report_to(&report_a, temp.path()).unwrap();
+        let path_b = save_report_to(&report_b, temp.path()).unwrap();
+
+        assert_ne!(
+            path_a, path_b,
+            "Different reports should have different paths"
+        );
+        assert!(path_a.exists());
+        assert!(path_b.exists());
+
+        let content_a: FailureReport =
+            serde_yaml::from_str(&std::fs::read_to_string(&path_a).unwrap()).unwrap();
+        let content_b: FailureReport =
+            serde_yaml::from_str(&std::fs::read_to_string(&path_b).unwrap()).unwrap();
+        assert_eq!(content_a.step_name, "step-a");
+        assert_eq!(content_b.step_name, "step-b");
+    }
+
+    // --- reports_dir ---
+
+    #[test]
+    fn reports_dir_ends_with_failure_reports() {
+        let dir = reports_dir();
+        assert!(
+            dir.ends_with("failure-reports"),
+            "Should end with failure-reports: {:?}",
+            dir
+        );
+        let parent = dir.parent().unwrap();
+        assert!(
+            parent.ends_with(".bivvy"),
+            "Parent should be .bivvy: {:?}",
+            parent
+        );
+    }
+
+    // --- FailureReport serialization ---
+
+    #[test]
